/* RESTORE_RECORD:articles */ {"id": 725, "url": "https://www.youtube.com/watch?v=HHMnpAzseew", "original_source_url": "https://www.youtube.com/watch?v=HHMnpAzseew", "source": "YouTube: Al Jazeera English", "source_status": "ACTIVE", "source_removed_notice": null, "source_last_checked_at": null, "creation_origin": "AI_SYNTHESIZED", "position_placement": "STANDARD", "display_order": 0, "is_pinned": false, "title": "Rohingya in Bangladesh preserve documents and memories of Myanmar in digital archive", "author": "Al Jazeera English", "published_at": "2026-09-24T08:06:30", "category": "international", "content_text": "Rohingya refugees in Bangladesh's Cox's Bazar are digitising family photographs, identity papers and land deeds to preserve proof of their heritage. More than a million fled persecution in Myanmar since 2017, and archivists hope the encrypted, decentralised collection will safeguard cultural memory for younger generations while potentially serving as evidence in ongoing ICC and ICJ cases against Myanmar. Many refugees also see the documents as vital for any future repatriation process.\n\nAl Jazeera's Tanvir Chowdhury reports from Cox's Bazar, Bangladesh.\n\nSubscribe to our channel: \nFollow us on X: \nFind us on Facebook: \nCheck our website: \nCheck out our Instagram page: \nDownload AJE Mobile App: \n\n#Bangladesh #CoxsBazar #Rohingya #Myanmar #RohingyaRefugees #RohingyaHistory #RohingyaDigitalArchive #RohingyaRefugeeCrisis #RohingyaHumanitarianCrisis #RohingyaRepatriation", "summary": "Rohingya in Bangladesh preserve documents and memories of Myanmar in digital archive", "extracted_entities": {"platform": "youtube", "video_id": "HHMnpAzseew", "channel_id": "UCNye-wNBqNL5ZzHSJj3l8Bg", "is_video_news": true}, "scrape_status": "completed", "missing_fields": [], "retry_count": 0, "is_featured": false, "is_breaking": false, "views_count": 0, "likes_count": 0, "shares_count": 0, "scheduled_at": null, "block_number": 701, "block_hash": "59fc0b77ea724f91dac89